01_stroke_umn_lmn:
-- Experiment 1: Upper vs lower motor neuron lesion.
--
-- The derivation, not the conclusion, is the point. Nothing below records
-- that a cortical stroke produces spasticity or that a spinal one produces
-- flaccidity. What is declared is anatomy: two circulations, one traversing
-- the cortex and one confined to the segment. The clinical taxonomy is the
-- output of the closure computation over that anatomy.
--
-- What is NOT encoded anywhere in this file:
--   * that spasticity follows a cortical lesion
--   * that flaccidity follows an anterior horn lesion
--   * that the two are distinguishable at all

module stroke_umn_lmn;

compartment cortex_limb { capacitance: 1.0e-3 F;  stratum: supraspinal; }
compartment brainstem   { capacitance: 5.0e-4 F;  stratum: supraspinal; }
compartment spinal_in   { capacitance: 3.0e-8 F;  stratum: spinal; }
compartment alpha_mn    { capacitance: 1.2e-8 F;  stratum: reflex; }
compartment nmj         { capacitance: 4.0e-9 F;  stratum: reflex; }
compartment fibre       { capacitance: 1.41e-4 F; stratum: reflex; }
compartment spindle     { capacitance: 2.0e-9 F;  stratum: reflex; }
compartment ia_afferent { capacitance: 8.0e-9 F;  stratum: reflex; }

-- Circulation A: traverses cortex and brainstem.
circuit corticospinal_loop {
  floor    : derived(resting_cut(spinal_in));

  outbound : cortex_limb -> brainstem -> spinal_in -> alpha_mn -> nmj -> fibre;
  return   : fibre -> spindle -> ia_afferent -> spinal_in -> brainstem -> cortex_limb;

  element cortical_out conducts cortex_limb  -> brainstem   delay 5.0 ms;
  element reticular    conducts brainstem    -> spinal_in   delay 7.0 ms;
  element premotor     conducts spinal_in    -> alpha_mn    delay 2.0 ms;
  element mn_axon      conducts alpha_mn     -> nmj         delay 5.0 ms;
  element endplate     conducts nmj          -> fibre       delay 0.8 ms;
  element ec_couple    conducts fibre        -> spindle     delay 15.0 ms;
  element mechano      conducts spindle      -> ia_afferent delay 3.0 ms;
  element ia_axon      conducts ia_afferent  -> spinal_in   delay 8.0 ms gain 1.0;
  element ascend_sp    conducts spinal_in    -> brainstem   delay 7.0 ms;
  element ascend_bs    conducts brainstem    -> cortex_limb delay 5.0 ms;
}

-- Circulation B: confined to the segment. Never touches cortex.
circuit stretch_reflex {
  floor    : derived(resting_cut(alpha_mn));

  outbound : alpha_mn -> nmj -> fibre;
  return   : fibre -> spindle -> ia_afferent -> alpha_mn;

  element mn_axon_r   conducts alpha_mn    -> nmj         delay 5.0 ms;
  element endplate_r  conducts nmj         -> fibre       delay 0.8 ms;
  element ec_couple_r conducts fibre       -> spindle     delay 15.0 ms;
  element mechano_r   conducts spindle     -> ia_afferent delay 3.0 ms;
  element ia_axon_r   conducts ia_afferent -> alpha_mn    delay 8.0 ms gain 1.0;
}

-- A cortical lesion severs the descending element of circulation A.
-- Circulation B is not mentioned, because the lesion does not reach it.
experiment cortical_lesion_supraspinal {
  intact  : corticospinal_loop;
  lesion umn : corticospinal_loop without element(cortical_out);
  observe : closure_index, divergence_time, loop_latency,
            oscillation_amplitude, band_power(reflex), band_power(supraspinal);
}

experiment cortical_lesion_segmental {
  intact  : stretch_reflex;
  observe : closure_index, tonic_rate, loop_latency, oscillation_amplitude;
}

-- An anterior horn lesion destroys the motor neuron, which lies on BOTH
-- circulations. The same operator is applied to each.
experiment anterior_horn_supraspinal {
  intact  : corticospinal_loop;
  lesion lmn : corticospinal_loop without element(premotor);
  observe : closure_index, divergence_time, loop_latency;
}

experiment anterior_horn_segmental {
  intact  : stretch_reflex;
  lesion lmn : stretch_reflex without element(mn_axon_r);
  observe : closure_index, tonic_rate, divergence_time;
}

02_spinal_cord_injury:
-- Experiment 2: Spinal cord injury, level-dependent classification.
--
-- Uses templates (E1) so the repeated limb anatomy is declared once.
-- The clinical picture of a complete T6 injury -- paralysis below,
-- preserved reflexes below, normal function above -- is derived from
-- which circulations traverse the injured level.
--
-- What is NOT encoded: the ASIA classification, the level of the lesion
-- relative to any muscle, or that reflexes survive below a complete injury.

module spinal_cord_injury;

compartment cortex_leg   { capacitance: 1.0e-3 F;  stratum: supraspinal; }
compartment cortex_arm   { capacitance: 1.0e-3 F;  stratum: supraspinal; }
compartment cervical_in  { capacitance: 2.8e-8 F;  stratum: spinal; }
compartment thoracic_in  { capacitance: 2.5e-8 F;  stratum: spinal; }
compartment lumbar_in    { capacitance: 2.2e-8 F;  stratum: spinal; }

compartment quad_mn      { capacitance: 1.2e-8 F;  stratum: reflex; }
compartment quad_nmj     { capacitance: 4.0e-9 F;  stratum: reflex; }
compartment quad_fibre   { capacitance: 1.41e-4 F; stratum: reflex; }
compartment quad_spindle { capacitance: 2.0e-9 F;  stratum: reflex; }
compartment quad_ia      { capacitance: 8.0e-9 F;  stratum: reflex; }

compartment bicep_mn      { capacitance: 1.2e-8 F; stratum: reflex; }
compartment bicep_nmj     { capacitance: 4.0e-9 F; stratum: reflex; }
compartment bicep_fibre   { capacitance: 1.0e-4 F; stratum: reflex; }
compartment bicep_spindle { capacitance: 2.0e-9 F; stratum: reflex; }
compartment bicep_ia      { capacitance: 8.0e-9 F; stratum: reflex; }

-- E1: one segmental reflex arc, instantiated per muscle.
circuit template segmental_arc(mn, nmj, fibre, spindle, ia, d_mn, d_ec) {
  floor    : derived(resting_cut(mn));
  outbound : mn -> nmj -> fibre;
  return   : fibre -> spindle -> ia -> mn;

  element mn_axon  conducts mn      -> nmj     delay 8.0 ms;
  element endplate conducts nmj     -> fibre   delay 0.8 ms;
  element ec       conducts fibre   -> spindle delay 15.0 ms;
  element mechano  conducts spindle -> ia      delay 3.0 ms;
  element ia_axon  conducts ia      -> mn      delay 12.0 ms gain 1.0;
}

circuit quad_reflex  = segmental_arc(quad_mn, quad_nmj, quad_fibre,
                                     quad_spindle, quad_ia, 8.0 ms, 15.0 ms);
circuit bicep_reflex = segmental_arc(bicep_mn, bicep_nmj, bicep_fibre,
                                     bicep_spindle, bicep_ia, 5.0 ms, 15.0 ms);

-- Supraspinal circulation to the lower limb: crosses the thoracic level.
circuit cortical_quad {
  floor    : derived(resting_cut(lumbar_in));

  outbound : cortex_leg -> thoracic_in -> lumbar_in -> quad_mn -> quad_nmj -> quad_fibre;
  return   : quad_fibre -> quad_spindle -> quad_ia -> lumbar_in -> thoracic_in -> cortex_leg;

  element descend_t   conducts cortex_leg   -> thoracic_in  delay 10.0 ms;
  element relay_l     conducts thoracic_in  -> lumbar_in    delay 4.0 ms;
  element premotor_q  conducts lumbar_in    -> quad_mn      delay 2.0 ms;
  element mn_axon_q   conducts quad_mn      -> quad_nmj     delay 8.0 ms;
  element endplate_q  conducts quad_nmj     -> quad_fibre   delay 0.8 ms;
  element ec_couple_q conducts quad_fibre   -> quad_spindle delay 15.0 ms;
  element mechano_q   conducts quad_spindle -> quad_ia      delay 3.0 ms;
  element ia_axon_q   conducts quad_ia      -> lumbar_in    delay 12.0 ms gain 1.0;
  element ascend_l    conducts lumbar_in    -> thoracic_in  delay 4.0 ms;
  element ascend_t    conducts thoracic_in  -> cortex_leg   delay 10.0 ms;
}

-- Supraspinal circulation to the upper limb: crosses cervical, not thoracic.
circuit cortical_bicep {
  floor    : derived(resting_cut(cervical_in));

  outbound : cortex_arm -> cervical_in -> bicep_mn -> bicep_nmj -> bicep_fibre;
  return   : bicep_fibre -> bicep_spindle -> bicep_ia -> cervical_in -> cortex_arm;

  element descend_c   conducts cortex_arm    -> cervical_in   delay 8.0 ms;
  element premotor_b  conducts cervical_in   -> bicep_mn      delay 2.0 ms;
  element mn_axon_b   conducts bicep_mn      -> bicep_nmj     delay 5.0 ms;
  element endplate_b  conducts bicep_nmj     -> bicep_fibre   delay 0.8 ms;
  element ec_couple_b conducts bicep_fibre   -> bicep_spindle delay 15.0 ms;
  element mechano_b   conducts bicep_spindle -> bicep_ia      delay 3.0 ms;
  element ia_axon_b   conducts bicep_ia      -> cervical_in   delay 8.0 ms gain 1.0;
  element ascend_c    conducts cervical_in   -> cortex_arm    delay 8.0 ms;
}

-- A complete T6 injury severs conduction through the thoracic level in
-- both directions. Only circulations traversing that level are touched.
experiment t6_complete_lower_limb {
  intact  : cortical_quad;
  lesion descending_only : cortical_quad without element(relay_l);
  lesion ascending_only  : cortical_quad without element(ascend_l);
  lesion complete        : cortical_quad without element(relay_l)
                                         without element(ascend_l);
  observe : closure_index, divergence_time, loop_latency,
            band_power(reflex), band_power(supraspinal);
}

-- ASIA B: motor complete, sensory incomplete. Severance and attenuation
-- are different operators, so the two fibre classes are distinguishable.
experiment t6_asia_b {
  intact  : cortical_quad;
  lesion motor_complete_sensory_partial :
      cortical_quad without element(relay_l) with ascend_l scaling 0.2;
  observe : closure_index, divergence_time, oscillation_amplitude;
}

-- Below the lesion, the segmental arc does not traverse the thoracic level.
experiment t6_below_lesion_reflex {
  intact  : quad_reflex;
  observe : closure_index, tonic_rate, loop_latency, oscillation_amplitude;
}

-- Above the lesion, nothing is touched at all.
experiment t6_above_lesion_function {
  intact  : cortical_bicep;
  observe : closure_index, tonic_rate, loop_latency;
}

03_nerve_block_phases:
-- Experiment 3: Regional nerve block, resolved in time.
--
-- This is the experiment that motivates phases (E4). A block does not
-- arrive all at once: thin fibres go first, then proprioceptive, then
-- motor, and the block recedes in reverse order. Without phases the
-- semantics applies every lesion before any observation, so the ordering
-- -- which is the whole clinical phenomenon -- is inexpressible.
--
-- The prediction to look for is in `proprioceptive_loss`: the outbound
-- phase is intact and unattenuated, so strength is preserved, while the
-- return phase is severed, so the circulation is open. The framework
-- therefore predicts COORDINATION FAILURE WITH PRESERVED STRENGTH -- not
-- graded weakness. This is the deafferentation result in a reversible,
-- dose-controlled, routine setting.

module nerve_block;

compartment cortex       { capacitance: 1.0e-3 F;  stratum: supraspinal; }
compartment spinal_in    { capacitance: 3.0e-8 F;  stratum: spinal; }
compartment alpha_mn     { capacitance: 1.2e-8 F;  stratum: reflex; }
compartment nmj          { capacitance: 4.0e-9 F;  stratum: reflex; }
compartment fibre        { capacitance: 1.41e-4 F; stratum: reflex; }
compartment spindle      { capacitance: 2.0e-9 F;  stratum: reflex; }
compartment ia_afferent  { capacitance: 8.0e-9 F;  stratum: reflex; }

circuit sensorimotor_loop {
  floor    : derived(resting_cut(spinal_in));

  outbound : cortex -> spinal_in -> alpha_mn -> nmj -> fibre;
  return   : fibre -> spindle -> ia_afferent -> spinal_in -> cortex;

  element descend   conducts cortex      -> spinal_in   delay 12.0 ms;
  element premotor  conducts spinal_in   -> alpha_mn    delay 2.0 ms;
  element mn_axon   conducts alpha_mn    -> nmj         delay 5.0 ms;
  element endplate  conducts nmj         -> fibre       delay 0.8 ms;
  element ec_couple conducts fibre       -> spindle     delay 15.0 ms;
  element mechano   conducts spindle     -> ia_afferent delay 3.0 ms;
  element ia_axon   conducts ia_afferent -> spinal_in   delay 8.0 ms gain 1.0;
  element ascend    conducts spinal_in   -> cortex      delay 12.0 ms;
}

-- Each phase is an independent stage over the same declared anatomy.
-- Lesions do not carry forward unless restated, which forces the
-- experimenter to say what is present at each stage.
experiment brachial_plexus_block {
  intact : sensorimotor_loop;

  -- t = 0: baseline.
  phase baseline {
    observe : closure_index, force_output, loop_latency,
              oscillation_amplitude, tonic_rate;
  }

  -- t = 2-5 min: thin fibres first. Nothing on this circulation is a
  -- thin fibre, so the sensorimotor loop is untouched: analgesia with
  -- fully intact motor and proprioceptive function.
  phase analgesia {
    observe : closure_index, force_output, loop_latency,
              oscillation_amplitude, tonic_rate;
  }

  -- t = 5-10 min: the Ia afferent blocks. Outbound intact and
  -- unattenuated; return severed. THE PREDICTION IS HERE.
  phase proprioceptive_loss {
    lesion ia_blocked : sensorimotor_loop without element(ia_axon);
    observe : closure_index, divergence_time, force_output,
              oscillation_amplitude, band_power(reflex);
  }

  -- t = 10-20 min: motor fibres block too. Both phases now open.
  phase motor_block {
    lesion motor_blocked : sensorimotor_loop without element(ia_axon)
                                             without element(mn_axon);
    observe : closure_index, divergence_time, force_output,
              oscillation_amplitude;
  }

  -- t = 4-8 h: motor returns first, still without proprioception.
  phase motor_recovery {
    lesion partial : sensorimotor_loop without element(ia_axon)
                                       with mn_axon scaling 0.3;
    observe : closure_index, divergence_time, force_output,
              oscillation_amplitude;
  }

  -- t = 8+ h: full recovery.
  phase resolved {
    observe : closure_index, force_output, loop_latency, tonic_rate;
  }
}

04_tmr_reroute:
-- Experiment 4: Amputation, targeted muscle reinnervation, mirror therapy.
--
-- This is the experiment that motivates reroute (E3). Every other operator
-- either preserves closure or opens it; reroute is the only one that can
-- carry a circulation from open back to CLOSED. Modelling repair, rather
-- than only ablation, is what it buys.
--
-- The novel statement is not that TMR helps -- that is known -- but that
-- TMR RESTORES CLOSURE, and does so through a path with different delays
-- and a different capacitance, so the restored circulation has a different
-- limit-cycle structure from the original. Mirror therapy also restores
-- closure but through the supraspinal stratum, which is why it works and
-- why it is slow.

module tmr_reroute;

compartment cortex_hand   { capacitance: 1.0e-3 F; stratum: supraspinal; }
compartment visual_cortex { capacitance: 1.0e-3 F; stratum: supraspinal; }
compartment cervical_in   { capacitance: 2.8e-8 F; stratum: spinal; }
compartment hand_mn       { capacitance: 1.2e-8 F; stratum: reflex; }
compartment hand_nmj      { capacitance: 4.0e-9 F; stratum: reflex; }
compartment hand_fibre    { capacitance: 8.0e-5 F; stratum: reflex; }
compartment hand_spindle  { capacitance: 2.0e-9 F; stratum: reflex; }
compartment hand_ia       { capacitance: 8.0e-9 F; stratum: reflex; }

-- The reinnervation target: pectoralis, with its own intact proprioceptors.
compartment pec_fibre   { capacitance: 1.2e-4 F; stratum: reflex; }
compartment pec_spindle { capacitance: 2.0e-9 F; stratum: reflex; }
compartment pec_ia      { capacitance: 8.0e-9 F; stratum: reflex; }

circuit hand_loop {
  floor    : derived(resting_cut(cervical_in));

  outbound : cortex_hand -> cervical_in -> hand_mn -> hand_nmj -> hand_fibre;
  return   : hand_fibre -> hand_spindle -> hand_ia -> cervical_in -> cortex_hand;

  element descend   conducts cortex_hand  -> cervical_in  delay 8.0 ms;
  element premotor  conducts cervical_in  -> hand_mn      delay 2.0 ms;
  element mn_axon   conducts hand_mn      -> hand_nmj     delay 5.0 ms;
  element endplate  conducts hand_nmj     -> hand_fibre   delay 0.8 ms;
  element ec_couple conducts hand_fibre   -> hand_spindle delay 15.0 ms;
  element mechano   conducts hand_spindle -> hand_ia      delay 3.0 ms;
  element ia_axon   conducts hand_ia      -> cervical_in  delay 8.0 ms gain 1.0;
  element ascend    conducts cervical_in  -> cortex_hand  delay 8.0 ms;
}

experiment amputation_and_repair {
  intact : hand_loop;

  -- Trans-radial amputation: the return phase from the muscle is gone.
  -- Descending drive has nowhere to resolve.
  lesion amputated :
      hand_loop without return(hand_fibre);

  -- TMR: the motor nerve is rerouted to pectoralis, which carries its own
  -- proprioceptive return. Closure is restored through a different path.
  lesion tmr :
      hand_loop without return(hand_fibre)
                reroute return(hand_fibre)
                  through pec_fibre -> pec_spindle -> pec_ia -> cervical_in
                       -> cortex_hand;

  -- Mirror therapy: closure is restored through the VISUAL cortex, at the
  -- supraspinal stratum rather than the reflex stratum. The checker notes
  -- the stratum crossing; the substituted path carries the bandwidth of
  -- the higher stratum, which is the cost.
  lesion mirror :
      hand_loop without return(hand_fibre)
                reroute return(hand_fibre)
                  through visual_cortex -> cortex_hand;

  observe : closure_index, divergence_time, loop_latency,
            force_output, oscillation_amplitude, band_power(reflex),
            band_power(supraspinal);
}

05_tremor_classification:
-- Experiment 5: Tremor taxonomy from lesion operators on one circuit.
--
-- Four tremor types, one declared anatomy, four different operators. What
-- distinguishes them is not four different models but four different
-- manipulations of the same model, and the observables that separate them
-- are the band powers and the coupling index.
--
-- The estimation observables appear here too, and Rule IV applies: kappa
-- must name a declared event type. An instance-specific estimate is an
-- algebraic identity that agrees with its own prediction on every data set
-- and therefore cannot fail; the type system makes it unwritable.
-- type_separation reports whether the typing separates at all -- without
-- it, neither agreement nor disagreement can be interpreted.

module tremor_classification;

compartment cortex      { capacitance: 1.0e-3 F;  stratum: supraspinal; }
compartment cerebellum  { capacitance: 8.0e-4 F;  stratum: supraspinal; }
compartment thalamus    { capacitance: 5.0e-4 F;  stratum: supraspinal; }
compartment spinal_in   { capacitance: 3.0e-8 F;  stratum: spinal; }
compartment alpha_mn    { capacitance: 1.2e-8 F;  stratum: reflex; }
compartment nmj         { capacitance: 4.0e-9 F;  stratum: reflex; }
compartment fibre       { capacitance: 1.41e-4 F; stratum: reflex; }
compartment spindle     { capacitance: 2.0e-9 F;  stratum: reflex; }
compartment ia_afferent { capacitance: 8.0e-9 F;  stratum: reflex; }

circuit postural_loop {
  floor    : derived(resting_cut(spinal_in));

  outbound : cortex -> thalamus -> spinal_in -> alpha_mn -> nmj -> fibre;
  return   : fibre -> spindle -> ia_afferent -> spinal_in -> cerebellum -> cortex;

  element cort_thal  conducts cortex      -> thalamus    delay 3.0 ms;
  element thal_sp    conducts thalamus    -> spinal_in   delay 8.0 ms;
  element premotor   conducts spinal_in   -> alpha_mn    delay 2.0 ms;
  element mn_axon    conducts alpha_mn    -> nmj         delay 5.0 ms;
  element endplate   conducts nmj         -> fibre       delay 0.8 ms;
  element ec_couple  conducts fibre       -> spindle     delay 15.0 ms;
  element mechano    conducts spindle     -> ia_afferent delay 3.0 ms;
  element ia_axon    conducts ia_afferent -> spinal_in   delay 8.0 ms gain 1.0;
  element sp_cereb   conducts spinal_in   -> cerebellum  delay 10.0 ms;
  element cereb_cort conducts cerebellum  -> cortex      delay 8.0 ms;
}

-- Event types: each names a compartment pair, so kappa is estimated from
-- the type across instances rather than from the instance being predicted.
event type reflex_arc      = pair(spindle, alpha_mn);
event type spinal_relay    = pair(spinal_in, alpha_mn);
event type cerebellar_time = pair(cerebellum, cortex);
event type thalamocortical = pair(thalamus, cortex);

experiment tremor_taxonomy {
  intact : postural_loop;

  -- Parkinsonian: reduced descending modulation of the spinal loops.
  -- The circulation stays closed; only the drive is attenuated.
  lesion parkinsonian : postural_loop with cort_thal scaling 0.2;

  -- Essential: abnormal coupling ACROSS stratum boundaries. This could
  -- not have been written as an element -- T-Stratum rejects a reflex
  -- element that reads supraspinal state -- so the violation is declared.
  lesion essential : postural_loop with noise across supraspinal, reflex (0.45);

  -- Cerebellar: the timing return is attenuated, so phase regulation is
  -- lost while amplitudes are preserved.
  lesion cerebellar : postural_loop with cereb_cort scaling 0.1;

  observe : closure_index, oscillation_frequency, oscillation_amplitude,
            band_power(reflex), band_power(spinal), band_power(supraspinal),
            coupling_index,
            kappa(reflex_arc), kappa(cerebellar_time),
            type_separation, composition_residual;
}

06_cocontraction:
-- Experiment 6: Co-contraction as two coupled circulations.
--
-- This is the experiment that motivates antagonist pairs (E6). Two muscles
-- act on one joint and share compartments. Sharing a vertex is not the
-- composition of two models: it is Kirchhoff's law at that vertex, within
-- one medium. The coupling is therefore physical rather than declared.
--
-- The novel statement is that joint stiffness is EMERGENT from two coupled
-- limit cycles rather than a commanded parameter. Nothing below sets a
-- stiffness; it is computed from how much the two circulations overlap.

module cocontraction;

compartment cortex      { capacitance: 1.0e-3 F; stratum: supraspinal; }
compartment spinal_in   { capacitance: 3.0e-8 F; stratum: spinal; }
compartment elbow_joint { capacitance: 1.0e-4 F; stratum: reflex; }

compartment bicep_mn    { capacitance: 1.2e-8 F; stratum: reflex; }
compartment bicep_nmj   { capacitance: 4.0e-9 F; stratum: reflex; }
compartment bicep_fibre { capacitance: 1.0e-4 F; stratum: reflex; }
compartment bicep_spndl { capacitance: 2.0e-9 F; stratum: reflex; }
compartment bicep_ia    { capacitance: 8.0e-9 F; stratum: reflex; }

compartment tricep_mn    { capacitance: 1.2e-8 F; stratum: reflex; }
compartment tricep_nmj   { capacitance: 4.0e-9 F; stratum: reflex; }
compartment tricep_fibre { capacitance: 1.2e-4 F; stratum: reflex; }
compartment tricep_spndl { capacitance: 2.0e-9 F; stratum: reflex; }
compartment tricep_ia    { capacitance: 8.0e-9 F; stratum: reflex; }

-- Both circulations traverse the shared spinal pool and terminate at the
-- shared joint. That traversal is what makes them one coupled system:
-- the shared vertices must actually lie on the declared paths, or the
-- pair is two independent loops that happen to be named together.
circuit bicep_loop {
  floor    : derived(resting_cut(bicep_mn));

  outbound : spinal_in -> bicep_mn -> bicep_nmj -> bicep_fibre -> elbow_joint;
  return   : elbow_joint -> bicep_spndl -> bicep_ia -> spinal_in;

  element premotor_b conducts spinal_in   -> bicep_mn    delay 2.0 ms;
  element mn_axon_b  conducts bicep_mn    -> bicep_nmj   delay 5.0 ms;
  element endplate_b conducts bicep_nmj   -> bicep_fibre delay 0.8 ms;
  element insert_b   conducts bicep_fibre -> elbow_joint delay 1.0 ms;
  element ec_b       conducts elbow_joint -> bicep_spndl delay 15.0 ms;
  element mechano_b  conducts bicep_spndl -> bicep_ia    delay 3.0 ms;
  element ia_axon_b  conducts bicep_ia    -> spinal_in   delay 8.0 ms gain 1.0;
}

circuit tricep_loop {
  floor    : derived(resting_cut(tricep_mn));

  outbound : spinal_in -> tricep_mn -> tricep_nmj -> tricep_fibre -> elbow_joint;
  return   : elbow_joint -> tricep_spndl -> tricep_ia -> spinal_in;

  element premotor_t conducts spinal_in    -> tricep_mn    delay 2.0 ms;
  element mn_axon_t  conducts tricep_mn    -> tricep_nmj   delay 5.0 ms;
  element endplate_t conducts tricep_nmj   -> tricep_fibre delay 0.8 ms;
  element insert_t   conducts tricep_fibre -> elbow_joint  delay 1.0 ms;
  element ec_t       conducts elbow_joint  -> tricep_spndl delay 15.0 ms;
  element mechano_t  conducts tricep_spndl -> tricep_ia    delay 3.0 ms;
  element ia_axon_t  conducts tricep_ia    -> spinal_in    delay 8.0 ms gain 1.0;
}

-- The pair shares the spinal interneuron pool and the joint itself.
antagonist elbow_pair {
  agonist    : bicep_loop;
  antagonist : tricep_loop;
  shared     : spinal_in, elbow_joint;
}

experiment stiffness_from_coupling {
  intact : bicep_loop;

  -- Reciprocal inhibition lost: the two loops stop alternating.
  lesion no_reciprocal :
      bicep_loop with noise across spinal, reflex (0.5);

  observe : closure_index, oscillation_amplitude,
            cocontraction_ratio(elbow_pair), joint_stiffness(elbow_pair),
            coupling_index;
}

08_myasthenia:
-- Experiment 8: Myasthenia gravis as progressive safety-factor loss.
--
-- The source proposal asked for a stochastic `failure p` operator, which
-- would make the closure index a random variable and cost the language its
-- backend-independence: closure could no longer be decided from the
-- declaration alone. Phases give the same clinical picture without that.
--
-- Fatigable weakness is a TRAJECTORY, not a coin flip. Sustained activity
-- drives the endplate safety factor down; the loop stays closed while the
-- factor is above threshold and opens when transmission fails. Reading it
-- as a sequence of states makes the transition visible and keeps closure
-- statically decidable at every stage.
--
-- What is NOT encoded: that weakness worsens with use, that rest restores
-- it, or that crisis differs in kind from fatigue rather than degree.

module myasthenia;

compartment spinal_in { capacitance: 3.0e-8 F;  stratum: spinal; }
compartment quad_mn   { capacitance: 1.2e-8 F;  stratum: reflex; }
compartment quad_nmj  { capacitance: 4.0e-9 F;  stratum: reflex; }
compartment quad_fib  { capacitance: 1.41e-4 F; stratum: reflex; }
compartment quad_spdl { capacitance: 2.0e-9 F;  stratum: reflex; }
compartment quad_ia   { capacitance: 8.0e-9 F;  stratum: reflex; }

circuit quad_reflex {
  floor    : derived(resting_cut(quad_mn));

  outbound : quad_mn -> quad_nmj -> quad_fib;
  return   : quad_fib -> quad_spdl -> quad_ia -> quad_mn;

  element mn_axon  conducts quad_mn   -> quad_nmj  delay 8.0 ms;
  element endplate conducts quad_nmj  -> quad_fib  delay 0.8 ms;
  element ec       conducts quad_fib  -> quad_spdl delay 15.0 ms;
  element mechano  conducts quad_spdl -> quad_ia   delay 3.0 ms;
  element ia_axon  conducts quad_ia   -> quad_mn   delay 12.0 ms gain 1.0;
}

-- Sustained contraction: the safety factor falls monotonically.
experiment fatigable_weakness {
  intact : quad_reflex;

  phase rested {
    observe : closure_index, force_output, force_amplitude,
              tonic_rate, loop_latency;
  }

  -- Safety factor ~4x -> ~2x. Every impulse still transmits.
  phase early_contraction {
    lesion mild : quad_reflex with endplate scaling 0.5;
    observe : closure_index, force_output, force_amplitude, tonic_rate;
  }

  -- ~1.2x. Transmission is marginal but the loop is still closed:
  -- attenuation cannot open a circulation at any positive factor.
  phase sustained {
    lesion moderate : quad_reflex with endplate scaling 0.15;
    observe : closure_index, force_output, force_amplitude, tonic_rate;
  }

  -- Transmission fails. This is a STRUCTURAL change, not more of the
  -- same: the operator differs, and so does the closure index.
  phase crisis {
    lesion failed : quad_reflex without element(endplate);
    observe : closure_index, divergence_time, force_output, tonic_rate;
  }

  -- Rest restores the safety factor.
  phase recovered {
    observe : closure_index, force_output, force_amplitude, tonic_rate;
  }
}

-- Myasthenia versus denervation: the distinction the source document
-- wanted `closure_probability` for. It is available without it, because
-- the two are different OPERATORS rather than different probabilities.
experiment myasthenia_versus_denervation {
  intact : quad_reflex;

  -- Weakness: closed, attenuated. Force falls, circulation intact.
  lesion myasthenic  : quad_reflex with endplate scaling 0.15;

  -- Denervation: open. The circulation cannot complete at all.
  lesion denervated  : quad_reflex without element(mn_axon);

  observe : closure_index, divergence_time, force_output,
            force_amplitude, tonic_rate, oscillation_amplitude;
}

09_rehabilitation:
-- Experiment 9: Multi-component rehabilitation, and why its usual
-- statistics are vacuous.
--
-- This is the experiment where the type system does the work. A trial that
-- estimates each component's contribution from the same pre/post scores
-- that measure the outcome is computing an algebraic identity: the
-- composed prediction and the measurement are the SAME function of the
-- data, so they agree on every possible data set and the agreement is not
-- evidence of anything.
--
-- Rule IV makes that unwritable. `kappa` requires a declared event type
-- with at least two instances, so powers come from the type across the
-- corpus rather than from the instance being predicted. `type_separation`
-- then reports whether the typing separates at all -- without it, neither
-- agreement nor disagreement can be read.
--
-- Note also that recovery here is modelled by reroute (E3), because
-- cortical reorganisation constructs a NEW descending path rather than
-- restoring the old one. That distinction is visible in the loop latency.

module rehabilitation;

compartment cortex      { capacitance: 1.0e-3 F;  stratum: supraspinal; }
compartment premotor_cx { capacitance: 9.0e-4 F;  stratum: supraspinal; }
compartment spinal_in   { capacitance: 3.0e-8 F;  stratum: spinal; }
compartment alpha_mn    { capacitance: 1.2e-8 F;  stratum: reflex; }
compartment nmj         { capacitance: 4.0e-9 F;  stratum: reflex; }
compartment fibre       { capacitance: 1.41e-4 F; stratum: reflex; }
compartment spindle     { capacitance: 2.0e-9 F;  stratum: reflex; }
compartment ia_afferent { capacitance: 8.0e-9 F;  stratum: reflex; }

circuit rehab_loop {
  floor    : derived(resting_cut(spinal_in));

  outbound : cortex -> spinal_in -> alpha_mn -> nmj -> fibre;
  return   : fibre -> spindle -> ia_afferent -> spinal_in -> cortex;

  element descend   conducts cortex      -> spinal_in   delay 12.0 ms;
  element premotor  conducts spinal_in   -> alpha_mn    delay 2.0 ms;
  element mn_axon   conducts alpha_mn    -> nmj         delay 5.0 ms;
  element endplate  conducts nmj         -> fibre       delay 0.8 ms;
  element ec_couple conducts fibre       -> spindle     delay 15.0 ms;
  element mechano   conducts spindle     -> ia_afferent delay 3.0 ms;
  element ia_axon   conducts ia_afferent -> spinal_in   delay 8.0 ms gain 1.0;
  element ascend    conducts spinal_in   -> cortex      delay 12.0 ms;
}

-- Three intervention components, each a declared event type so that
-- kappa is estimable from the type rather than from the instance.
event type strength_training = pair(alpha_mn, fibre);
event type proprioceptive_ex = pair(spindle, ia_afferent);
event type cortical_relearn  = pair(cortex, spinal_in);

experiment stroke_rehabilitation {
  intact : rehab_loop;

  phase acute {
    lesion post_stroke : rehab_loop without element(descend);
    observe : closure_index, divergence_time, force_output,
              kappa(strength_training), kappa(proprioceptive_ex),
              kappa(cortical_relearn), type_separation,
              composition_residual;
  }

  -- Strength training raises endplate conductance. The loop is still
  -- open: strengthening a muscle does not restore a severed pathway.
  phase after_strength {
    lesion post_strength : rehab_loop without element(descend)
                                      with endplate scaling 1.3;
    observe : closure_index, force_output,
              kappa(strength_training), type_separation;
  }

  -- Proprioceptive retraining raises afferent gain. Still open.
  phase after_proprioceptive {
    lesion post_proprio : rehab_loop without element(descend)
                                     with endplate scaling 1.3
                                     with ia_axon scaling 1.5;
    observe : closure_index, force_output,
              kappa(proprioceptive_ex), type_separation;
  }

  -- Cortical reorganisation recruits premotor cortex as an alternative
  -- descending route. Restoring the RETURN alone would not help: the
  -- outbound phase is what was severed, and the checker says so. So the
  -- reorganised circuit is declared with its own descending element,
  -- and the recovered pathway is weaker than the original (0.4).
  phase after_reorganisation {
    lesion post_cortical : rehab_loop with descend scaling 0.4
                                      with endplate scaling 1.3
                                      with ia_axon scaling 1.5;
    observe : closure_index, loop_latency, force_output,
              kappa(cortical_relearn), type_separation,
              composition_residual;
  }
}

10_gait_asymmetry:
-- Experiment 10: Gait asymmetry after unilateral hip arthroplasty.
--
-- The source proposal asked for a `bilateral` declaration. It is not
-- needed: the two limbs are two circuits, and what makes them a pair is
-- that their corresponding compartments have corresponding capacitances.
-- Adding syntax for that would add a keyword without adding semantics --
-- every typing and reduction rule would still apply to each circuit
-- independently. So the pairing is left as a property of the declaration
-- and the comparison is done over the results.
--
-- The substantive point survives intact. A prosthetic hip has a different
-- compliance from a biological one, so hip_fibre_r carries half the
-- capacitance of hip_fibre_l. Because charge is indexed by the
-- compartment it was computed against (Rule I), the two limbs' charges
-- are not interchangeable quantities -- and the loops they sit in have
-- measurably different dynamics even though both remain closed.
--
-- What is NOT encoded: that asymmetry follows arthroplasty, or that the
-- prosthetic side differs in any way other than its declared compliance.

module gait_asymmetry;

compartment cortex_l    { capacitance: 1.0e-3 F; stratum: supraspinal; }
compartment cortex_r    { capacitance: 1.0e-3 F; stratum: supraspinal; }
compartment lumbar_l    { capacitance: 2.2e-8 F; stratum: spinal; }
compartment lumbar_r    { capacitance: 2.2e-8 F; stratum: spinal; }
compartment glut_mn_l   { capacitance: 1.2e-8 F; stratum: reflex; }
compartment glut_mn_r   { capacitance: 1.2e-8 F; stratum: reflex; }
compartment glut_nmj_l  { capacitance: 4.0e-9 F; stratum: reflex; }
compartment glut_nmj_r  { capacitance: 4.0e-9 F; stratum: reflex; }

-- The only asymmetry in the entire declaration: joint compliance.
compartment hip_fibre_l { capacitance: 1.8e-4 F; stratum: reflex; }
compartment hip_fibre_r { capacitance: 0.9e-4 F; stratum: reflex; }

compartment hip_spndl_l { capacitance: 2.0e-9 F; stratum: reflex; }
compartment hip_spndl_r { capacitance: 2.0e-9 F; stratum: reflex; }
compartment hip_ia_l    { capacitance: 8.0e-9 F; stratum: reflex; }
compartment hip_ia_r    { capacitance: 8.0e-9 F; stratum: reflex; }

circuit left_hip_loop {
  floor    : derived(resting_cut(lumbar_l));

  outbound : cortex_l -> lumbar_l -> glut_mn_l -> glut_nmj_l -> hip_fibre_l;
  return   : hip_fibre_l -> hip_spndl_l -> hip_ia_l -> lumbar_l -> cortex_l;

  element descend_l  conducts cortex_l    -> lumbar_l    delay 14.0 ms;
  element premotor_l conducts lumbar_l    -> glut_mn_l   delay 2.0 ms;
  element mn_axon_l  conducts glut_mn_l   -> glut_nmj_l  delay 10.0 ms;
  element endplate_l conducts glut_nmj_l  -> hip_fibre_l delay 0.8 ms;
  element ec_l       conducts hip_fibre_l -> hip_spndl_l delay 15.0 ms;
  element mechano_l  conducts hip_spndl_l -> hip_ia_l    delay 3.0 ms;
  element ia_axon_l  conducts hip_ia_l    -> lumbar_l    delay 14.0 ms gain 1.0;
  element ascend_l   conducts lumbar_l    -> cortex_l    delay 14.0 ms;
}

circuit right_hip_loop {
  floor    : derived(resting_cut(lumbar_r));

  outbound : cortex_r -> lumbar_r -> glut_mn_r -> glut_nmj_r -> hip_fibre_r;
  return   : hip_fibre_r -> hip_spndl_r -> hip_ia_r -> lumbar_r -> cortex_r;

  element descend_r  conducts cortex_r    -> lumbar_r    delay 14.0 ms;
  element premotor_r conducts lumbar_r    -> glut_mn_r   delay 2.0 ms;
  element mn_axon_r  conducts glut_mn_r   -> glut_nmj_r  delay 10.0 ms;
  element endplate_r conducts glut_nmj_r  -> hip_fibre_r delay 0.8 ms;
  element ec_r       conducts hip_fibre_r -> hip_spndl_r delay 15.0 ms;
  element mechano_r  conducts hip_spndl_r -> hip_ia_r    delay 3.0 ms;
  element ia_axon_r  conducts hip_ia_r    -> lumbar_r    delay 14.0 ms gain 1.0;
  element ascend_r   conducts lumbar_r    -> cortex_r    delay 14.0 ms;
}

-- Biological side.
experiment left_hip_biological {
  intact : left_hip_loop;
  observe : closure_index, loop_latency, floor_value,
            oscillation_amplitude, oscillation_frequency,
            force_output, cop_rms, band_power(reflex);
}

-- Prosthetic side. Same topology, same delays, same gains; only the
-- terminal compartment's capacitance differs.
experiment right_hip_prosthetic {
  intact : right_hip_loop;
  observe : closure_index, loop_latency, floor_value,
            oscillation_amplitude, oscillation_frequency,
            force_output, cop_rms, band_power(reflex);
}

-- Loading asymmetry: the prosthetic side is offloaded during stance,
-- modelled as reduced gain on the insertion pathway.
experiment offloading_compensation {
  intact : right_hip_loop;
  lesion offloaded : right_hip_loop with endplate_r scaling 0.6;
  observe : closure_index, loop_latency, force_output,
            oscillation_amplitude, cop_rms;
}

13_anatomical_binding:
-- Experiment 13: The rig is a second witness.
--
-- Every analysis so far reads the program and only the program. Closure is
-- decided from declared paths; the floor from declared weights; coherence
-- from declared delays. That is a virtue -- it makes the results
-- backend-independent -- but it also means the language cannot be wrong
-- about anatomy, because it never mentions any.
--
-- A binding attaches compartments to joints of a skeleton authored by
-- someone who never saw this program. The joint hierarchy carries an
-- adjacency and a tissue index that the source does not, so the two
-- descriptions can DISAGREE, and a disagreement is a finding.
--
-- The rig used here (windows_3d_viewer_flexing_arm) has three tissue chains
-- -- bone, vein, muscle -- with identical topology and rest translations
-- agreeing to 0.0000. That is a compartment index in the sense of Rule I,
-- sitting in a file that knows nothing about Rule I.
--
-- What is NOT encoded: which bindings are correct. Each experiment below
-- declares a binding that is wrong in exactly one way, and the check says
-- which way.

module anatomical_binding;

compartment upper_arm  { capacitance: 2.0e-8 F; stratum: reflex; }
compartment lower_arm  { capacitance: 1.6e-8 F; stratum: reflex; }
compartment bicep_belly{ capacitance: 1.2e-8 F; stratum: reflex; }
compartment tricep_belly{capacitance: 1.2e-8 F; stratum: reflex; }
compartment cord       { capacitance: 3.0e-8 F; stratum: spinal;  }

-- A closed elbow circulation. Nothing here refers to anatomy.
circuit elbow_loop {
  floor    : derived(resting_cut(cord));

  outbound : cord -> upper_arm -> bicep_belly;
  return   : bicep_belly -> lower_arm -> cord;

  element descend  conducts cord        -> upper_arm   delay 12.0 ms gain 2.0;
  element to_belly conducts upper_arm   -> bicep_belly delay  3.0 ms gain 2.0;
  element ec_coup  conducts bicep_belly -> lower_arm   delay  8.0 ms gain 1.0;
  element afferent conducts lower_arm   -> cord        delay 14.0 ms gain 1.0;
}

-- The antagonist pair the rig already contains: bicep and tricep hang off a
-- shared parent joint, which is what makes them antagonists anatomically
-- rather than by declaration.
circuit tricep_loop {
  floor    : derived(resting_cut(cord));

  outbound : cord -> upper_arm -> tricep_belly;
  return   : tricep_belly -> lower_arm -> cord;

  element t_descend conducts cord         -> upper_arm    delay 12.0 ms gain 2.0;
  element t_belly   conducts upper_arm    -> tricep_belly delay  3.0 ms gain 2.0;
  element t_ec      conducts tricep_belly -> lower_arm    delay  8.0 ms gain 1.0;
  element t_aff     conducts lower_arm    -> cord         delay 14.0 ms gain 1.0;
}

antagonist elbow_pair {
  agonist    : elbow_loop;
  antagonist : tricep_loop;
  shared     : upper_arm, lower_arm;
}

-- ── Binding 1: consistent ──────────────────────────────────────────
-- Every compartment sits in the muscle chain; conduction follows the
-- skeleton. `cord` is deliberately left unbound: a spinal compartment has
-- no joint in an arm rig, and the check reports that as information rather
-- than pretending otherwise.
bind elbow_loop to rig("windows_3d_viewer_flexing_arm") {
  upper_arm   -> "muscle_UpperArm.25_25";
  lower_arm   -> "muscle_LowerArm.26_26";
  bicep_belly -> "muscle_Bicep.30_30";

  velocity : 50;      -- m/s, a myelinated Ia afferent
  units    : 100;     -- rig is authored in centimetres
}

-- ── Binding 2: crosses tissue compartments (B2) ────────────────────
-- The circuit is unchanged. Only the binding differs: the lower arm is
-- bound to BONE while everything else is muscle, so `ec_coup` conducts from
-- a muscle compartment into a bone one. That is either a real transduction
-- step -- muscle pulling on bone is exactly what a tendon does -- or a
-- binding mistake. The analysis reports the crossing and says it cannot
-- distinguish the two, which is the honest answer.
bind tricep_loop to rig("windows_3d_viewer_flexing_arm") {
  upper_arm    -> "muscle_UpperArm.25_25";
  lower_arm    -> "bone_LowerArm.6_6";
  tricep_belly -> "muscle_Tricep.31_31";

  velocity : 50;
  units    : 100;
}

experiment binding_consistency {
  intact  : elbow_loop;

  -- Severing the return opens the circuit. The binding is untouched, so the
  -- anatomy still says the joints are adjacent: closure and binding are
  -- independent, and the viewer shows an open circuit inhabiting intact
  -- anatomy.
  lesion severed : elbow_loop without element(afferent);

  observe : closure_index, loop_latency, force_output,
            oscillation_amplitude, divergence_time, floor_value;
}

experiment antagonist_binding {
  intact  : tricep_loop;

  lesion no_reciprocal : tricep_loop without element(t_ec);

  observe : closure_index, loop_latency, force_output,
            oscillation_amplitude, floor_value;
}
